from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[0] * w for _ in range(h)]  # 0 represents an empty cell

    def is_valid(row: int, col: int, tile_h: int, tile_w: int) -> bool:
        """Checks if a tile can be placed at the given position."""
        if row + tile_h > h or col + tile_w > w:
            return False
        for i in range(row, row + tile_h):
            for j in range(col, col + tile_w):
                if grid[i][j] != 0:
                    return False
        return True

    def place_tile(row: int, col: int, tile_h: int, tile_w: int, tile_id: int) -> None:
        """Places a tile on the grid."""
        for i in range(row, row + tile_h):
            for j in range(col, col + tile_w):
                grid[i][j] = tile_id

    def remove_tile(row: int, col: int, tile_h: int, tile_w: int) -> None:
        """Removes a tile from the grid."""
        for i in range(row, row + tile_h):
            for j in range(col, col + tile_w):
                grid[i][j] = 0

    def solve(tile_index: int) -> bool:
        """Recursive backtracking function to solve the tiling problem."""
        if tile_index == n:
            # All tiles have been considered. Check if the grid is fully covered.
            for i in range(h):
                for j in range(w):
                    if grid[i][j] == 0:
                        return False  # Grid is not fully covered
            return True  # Grid is fully covered

        for row in range(h):
            for col in range(w):
                if grid[row][col] == 0:  # Find an empty cell
                    # Try placing the current tile with its original dimensions
                    a, b = tiles[tile_index]
                    if is_valid(row, col, a, b):
                        place_tile(row, col, a, b, tile_index + 1)
                        if solve(tile_index + 1):
                            return True
                        remove_tile(row, col, a, b)

                    # Try placing the tile rotated
                    if a != b and is_valid(row, col, b, a):
                        place_tile(row, col, b, a, tile_index + 1)
                        if solve(tile_index + 1):
                            return True
                        remove_tile(row, col, b, a)

                    return False  # No placement of the current tile works

        return False  # No empty cell found, unsolvable

    return solve(0)
