    tiles_area = sum(a * b for a, b in tiles)

    if grid_area > tiles_area:
        return False

    grid = [[0] * w for _ in range(h)]

    def fits(tile_a, tile_b, row, col):
        if row + tile_a > h or col + tile_b > w:
            return False
        for i in range(row, row + tile_a):
            for j in range(col, col + tile_b):
                if grid[i][j] == 1:
                    return False
        return True

    def place_tile(tile_a, tile_b, row, col):
